SELECT t.TASK_ID AS row_id, t.ACTIVE_FLAG AS active_flag, 'Y' AS well_formed, t.PIPELINE_ID AS pipeline_id, p.PIPELINE_CODE AS pipeline_code, t.TASK_CODE AS task_code, t.TASK_TYPE AS task_type, t.HANDLER AS handler, t.RUN_CONDITION AS run_condition, t.RUN_CONDITION_COUNT AS run_condition_count, t.TARGET_TABLE_ID AS target_table_id, t.TARGET_ACTIVE_FLAG AS target_active_flag, o.CATALOG_NAME AS target_catalog_name, o.SCHEMA_NAME AS target_schema_name, o.TABLE_NAME AS target_table_name FROM CFG_TASKS t JOIN CFG_PIPELINES p ON p.PIPELINE_ID = t.PIPELINE_ID LEFT JOIN CFG_TABLES o ON o.TABLE_ID=t.TARGET_TABLE_ID WHERE p.PROJECT_ID=:project_id ORDER BY 1
